// swift-tools-version: 6.2
import PackageDescription

// Java bindings for the Android app, generated by swift-java (JNI mode).
// A separate package, so the Apple apps never resolve swift-java.
let package = Package(
    name: "SpaceStateKitAndroid",
    platforms: [.macOS(.v26)],
    products: [
        .library(name: "SpaceStateKitAndroid", type: .dynamic, targets: ["SpaceStateKitAndroid"]),
    ],
    dependencies: [
        .package(name: "SpaceStateKit", path: ".."),
        .package(url: "https://github.com/swiftlang/swift-java.git", exact: "0.6.0"),
    ],
    targets: [
        .target(
            name: "SpaceStateKitAndroid",
            dependencies: [
                .product(name: "SpaceAPI", package: "SpaceStateKit"),
                .product(name: "MainframeStatus", package: "SpaceStateKit"),
                .product(name: "SpacePushClient", package: "SpaceStateKit"),
                .product(name: "SwiftJava", package: "swift-java"),
            ],
            exclude: ["swift-java.config"],
            plugins: [.plugin(name: "JExtractSwiftPlugin", package: "swift-java")]
        ),
    ]
)
